# Filename: ADC_Code.py
# Description: Reads analog inputs from an ADS1x15 ADC and prints the values.
# Author: Bard
# Date: 2023-11-28

import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS1115
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_BUS = 1  # I2C bus number
ADS1115_ADDRESS = 0x48  # I2C address of the ADS1115
READ_INTERVAL_SECONDS = 0.5  # Time between readings
NUMBER_OF_CHANNELS = 4  # Number of ADC channels to read

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the ADS1115 ADC."""
    try:
        return ADS1115(i2c_bus, address=ADS1115_ADDRESS)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def initialize_analog_inputs(adc, gain=1):
    """Initializes analog input objects for each channel."""
    return [AnalogIn(adc, ADS1115.P0 + i, gain=gain) for i in range(NUMBER_OF_CHANNELS)]

def read_adc_values(analog_inputs):
    """Reads the raw ADC values from all channels."""
    return [channel.value for channel in analog_inputs]

def print_header():
    """Prints the header row for the ADC values table."""
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*['Channel {}'.format(i) for i in range(NUMBER_OF_CHANNELS)]))
    print('-' * 37)

def print_adc_values(values):
    """Prints the ADC values in a formatted table row."""
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*values))

def main():
    """Main function to read and display ADC values."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return

    analog_inputs = initialize_analog_inputs(adc)

    try:
        print_header()
        while True:
            adc_values = read_adc_values(analog_inputs)
            print_adc_values(adc_values)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or ADC in this library, but good practice to include a placeholder
        print("Program finished.")

if __name__ == "__main__":
    main()

