import atexit
import threading
import time
import signal
import logging
from flask import Flask, render_template, Response
from picamera2 import Picamera2, Preview
import cv2

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Import configuration and mail functions
try:
    import config
    import mail_config
except ImportError as e:
    logging.error(f"Error importing configuration or mail functions: {e}. Ensure config.py and mail_config.py are in the same directory.")
    exit(1)

# Global variables
output_frame = None
frame_lock = threading.Lock()
last_epoch = 0
app = Flask(__name__)

class Camera:
    def __init__(self):
        self.camera = None
        self.video_stream = None
        self.video_config = None
        self.initialize_camera()

    def initialize_camera(self):
        """Initializes the camera with error handling."""
        try:
            self.camera = Picamera2()
            if config.camera_type == 'still':
                self.camera.configure(self.camera.create_still_configuration(main={"size": (640, 480)}))
            elif config.camera_type == 'video':
                self.camera.configure(self.camera.create_video_configuration(main={"size": (640, 480)}))
            else:
                logging.error(f"Invalid camera_type: {config.camera_type}. Must be 'still' or 'video'.")
                return False

            self.camera.transform = config.get_camera_transform()
            self.camera.start()
            logging.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            return False

    def get_frame(self):
        """Returns the current camera frame as a JPEG byte stream."""
        global frame_lock, output_frame
        try:
            with frame_lock:
                if output_frame is None:
                    return None
                frame = output_frame.copy()  # Create a copy to avoid race conditions
            _, jpeg = cv2.imencode('.jpg', frame)
            return jpeg.tobytes()
        except Exception as e:
            logging.error(f"Error getting frame: {e}")
            return None

    @staticmethod
    def frames():
        """Generator function to continuously capture and yield frames."""
        global output_frame, frame_lock, last_epoch, camera

        while True:
            try:
                if config.camera_type == 'still':
                    frame = camera.capture_array()
                elif config.camera_type == 'video':
                    frame = camera.capture_array()
                else:
                    logging.error(f"Invalid camera_type: {config.camera_type}. Must be 'still' or 'video'.")
                    break

                with frame_lock:
                    output_frame = frame

                current_epoch = time.time()
                if config.send_email_notifications and (current_epoch - last_epoch) > config.email_send_interval:
                    try:
                        if config.classifier_name == 'motion_detector':
                            _, detected = camera.get_object_with_basic_motion_detection()
                        else:
                            _, detected = camera.get_object(config.classifier_name)

                        if detected:
                            logging.info("Object detected!")
                            mail_config.send_email(frame, config)
                            last_epoch = current_epoch
                    except Exception as e:
                        logging.error(f"Error sending email: {e}")

                time.sleep(0.1)  # Adjust sleep time as needed

            except Exception as e:
                logging.error(f"Error in camera frames generator: {e}")
                break  # Exit the loop on error

    def get_object(self, classifier_name):
        """Performs object detection using the specified classifier."""
        try:
            if config.camera_type == 'still':
                frame = self.camera.capture_array()
            elif config.camera_type == 'video':
                frame = self.camera.capture_array()
            else:
                logging.error(f"Invalid camera_type: {config.camera_type}. Must be 'still' or 'video'.")
                return None, False

            gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            if classifier_name == 'motion_detector':
                _, detected = self.camera.get_object_with_basic_motion_detection()
            elif classifier_name == 'face_detector':
                detected = self.camera.detect_face(gray_frame)
            elif classifier_name == 'car_detector':
                detected = self.camera.detect_car(gray_frame)
            else:
                logging.warning(f"Unknown classifier name: {classifier_name}")
                detected = False

            return frame, detected
        except Exception as e:
            logging.error(f"Error performing object detection: {e}")
            return None, False

    def get_object_with_basic_motion_detection(self):
        """Detects motion using frame differencing."""
        try:
            if config.camera_type == 'still':
                frame = self.camera.capture_array()
            elif config.camera_type == 'video':
                frame = self.camera.capture_array()
            else:
                logging.error(f"Invalid camera_type: {config.camera_type}. Must be 'still' or 'video'.")
                return None, False

            gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            gray_frame = cv2.GaussianBlur(gray_frame, (21, 21), 0)

            global previous_frame
            if previous_frame is None:
                previous_frame = gray_frame
                return frame, False

            frame_delta = cv2.absdiff(previous_frame, gray_frame)
            thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
            thresh = cv2.dilate(thresh, None, iterations=2)
            contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

            for contour in contours:
                if cv2.contourArea(contour) < config.min_motion_area:
                    continue

                (x, y, w, h) = cv2.boundingRect(contour)
                cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
                detected = True

            previous_frame = gray_frame
            return frame, detected

        except Exception as e:
            logging.error(f"Error in motion detection: {e}")
            return None, False


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Shutting down...")
    global camera
    if camera:
        camera.stop()
    exit(0)


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Initialize camera globally
camera = Camera()
previous_frame = None  # Initialize previous frame for motion detection

if not camera.camera:
    print("Failed to initialize camera. Exiting.")
    exit(1)

def check_for_objects():
    """Continuously checks for objects and sends email notifications."""
    global camera
    while True:
        try:
            if config.send_email_notifications:
                if config.classifier_name == 'motion_detector':
                    _, detected = camera.get_object_with_basic_motion_detection()
                else:
                    _, detected = camera.get_object(config.classifier_name)

                if detected:
                    logging.info("Object detected!")
                    mail_config.send_email(camera.camera.capture_array(), config)
                    time.sleep(config.email_send_interval)  # Wait before checking again
            else:
                time.sleep(1)  # Check every second if email notifications are disabled
        except Exception as e:
            logging.error(f"Error in object detection loop: {e}")
            time.sleep(5)  # Wait before retrying


def generate():
    """Generates the video feed for the web page."""
    global camera
    while True:
        frame = camera.get_frame()
        if frame is None:
            continue
        yield (b'--frame\r\n'
               b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')


@app.route('/', methods=['GET', 'POST'])
def index():
    """Renders the HTML index page with the configuration form."""
    global config
    if request.method == 'POST':
        try:
            config.classifier_name = request.form.get('classifier')
            config.live_preview = request.form.get('live_preview') == 'on'
            config.send_email_notifications = request.form.get('send_email') == 'on'
            config.recipient_email_address = request.form.get('recipient_email')
            config.sender_email_address = request.form.get('sender_email')
            config.email_password = request.form.get('email_password')
            config.email_send_interval = int(request.form.get('email_send_interval'))
            config.min_motion_area = int(request.form.get('min_motion_area'))
            config.camera_type = request.form.get('camera_type')
            config.camera_transform = request.form.get('camera_transform')

            logging.info("Configuration updated.")
        except ValueError as e:
            logging.error(f"Invalid input: {e}")
            return render_template('index.html', config=config, error_message="Invalid input. Please check your values.")
        except Exception as e:
            logging.error(f"Error updating configuration: {e}")
            return render_template('index.html', config=config, error_message="Error updating configuration.")

    return render_template('index.html', config=config)


@app.route('/video_feed')
def video_feed():
    """Returns the video feed as a multipart/x-mixed-replace stream."""
    return Response(generate(),
                    mimetype='multipart/x-mixed-replace; boundary=frame')


if __name__ == '__main__':
    # Start the object detection thread
    object_detection_thread = threading.Thread(target=check_for_objects)
    object_detection_thread.daemon = True  # Allow the main thread to exit even if this thread is running
    object_detection_thread.start()

    # Start the camera frames generator in a separate thread
    camera_thread = threading.Thread(target=camera.frames)
    camera_thread.daemon = True
    camera_thread.start()

    # Start the Flask app
    app.run(host='0.0.0.0', debug=False, threaded=True)

