import serial
import time
import sys

# Define serial port and baud rate
BLUETOOTH_PORT = '/dev/rfcomm4'
BLUETOOTH_BAUD_RATE = 38400

def initialize_bluetooth(port, baudrate):
    """Initializes the Bluetooth serial connection."""
    try:
        bluetooth = serial.Serial(port, baudrate, timeout=1)
        return bluetooth
    except serial.SerialException as e:
        print(f"Error opening Bluetooth port: {e}", file=sys.stderr)
        return None

def send_data(bluetooth_connection, data):
    """Sends data over the Bluetooth connection."""
    try:
        bluetooth_connection.write(f'X{data}'.encode('utf-8'))
        print(f'Sent: {data}')
    except serial.SerialException as e:
        print(f"Error sending data: {e}", file=sys.stderr)

def main():
    """Main function to handle user input and send data."""
    bluetooth = initialize_bluetooth(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)

    if bluetooth is None:
        print("Failed to initialize Bluetooth. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input('Enter data to send (or "q" to quit): ')
                if user_input.lower() == 'q':
                    break
                send_data(bluetooth, user_input)
            except KeyboardInterrupt:
                print("\nExiting program.", file=sys.stderr)
                break
    finally:
