    """Initializes the Bluetooth serial connection."""
    try:
        bluetooth = serial.Serial(port, baudrate, timeout=1)
        return bluetooth
    except serial.SerialException as e:
        print(f"Error opening Bluetooth port: {e}", file=sys.stderr)
        return None

