#!/usr/bin/env python3

# Script Name: home_automation_temp_humidity.py
# Author: Bard
# Date: October 26, 2023
# Description: Monitors temperature and humidity using a DHT22 sensor and provides home automation status.
# Hardware Requirements: Raspberry Pi 3 Model B+, DHT22 sensor, LED (optional).
# Software Requirements: Python 3, adafruit_circuitpython_dht, gpiozero, logging, time, signal, sys

import adafruit_circuitpython_dht
import gpiozero
import logging
import time
import signal
import sys

# Configuration dictionary
CONFIG = {
    'dht_pin': 4,  # GPIO pin connected to the DHT22 data pin
    'led_pin': 17, # GPIO pin connected to the LED (optional)
    'read_interval': 5, # Time in seconds between sensor readings
    'log_level': logging.INFO # Logging level (DEBUG, INFO, WARNING, ERROR, CRITICAL)
}

# Initialize logging
logging.basicConfig(
    level=CONFIG['log_level'],
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler("home_automation.log"),
        logging.StreamHandler()
    ]
)

# Initialize DHT22 sensor
dht_device = adafruit_circuitpython_dht.DHT22(CONFIG['dht_pin'])

# Initialize LED (optional)
try:
    led = gpiozero.LED(CONFIG['led_pin'])
except gpiozero.exc.GPIODeviceError as e:
    logging.warning(f"LED initialization failed: {e}. Continuing without LED.")
    led = None

# Global variable to track program state
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logging.info("Received signal, shutting down...")
    running = False
    if led:
        led.off() # Turn off LED on shutdown
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def read_sensor_data():
    """Reads temperature and humidity from the DHT22 sensor."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
        else:
            logging.warning("Failed to read sensor data.")
            return None, None
    except RuntimeError as e:
        # Errors happen fairly often, DHT's are hard to read, just keep going
        logging.error(f"DHT22 RuntimeError: {e}")
        return None, None
    except Exception as e:
        logging.error(f"DHT22 Error: {e}")
        return None, None

def update_status(temperature, humidity):
    """Updates the LED status based on temperature and humidity."""
    if temperature is not None and humidity is not None:
        if temperature > 25:
            logging.warning(f"High temperature: {temperature:.1f}°C")
            if led:
                led.blink(on_time=0.5, off_time=0.5) # Blink LED
        elif humidity < 40:
            logging.warning(f"Low humidity: {humidity:.1f}%")
            if led:
                led.blink(on_time=0.5, off_time=0.5) # Blink LED
        else:
            if led:
                led.on() # Solid LED
    else:
        logging.error("Sensor data is invalid.")
        if led:
            led.off() # Turn off LED

def main():
    """Main function to read sensor data and update status."""
    logging.info("Starting home automation temperature and humidity monitor.")
    if led:
        led.blink(on_time=0.5, off_time=0.5) # Initial blink to indicate startup
    try:
        while running:
            temperature, humidity = read_sensor_data()
            if temperature is not None and humidity is not None:
                logging.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                update_status(temperature, humidity)
            else:
                logging.error("Failed to read sensor data.")
                if led:
                    led.off() # Turn off LED
            time.sleep(CONFIG['read_interval'])
    except Exception as e:
        logging.critical(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Exiting home automation temperature and humidity monitor.")
        if led:
            led.off() # Ensure LED is off on exit

if __name__ == "__main__":
    main()

