# Script to read altitude from a BMP280 sensor on a Raspberry Pi
# Uses the adafruit_bmp280 library

import time
import board
import busio
import adafruit_bmp280

# Define the I2C address of the BMP280 sensor
BMP280_ADDRESS = 0x76

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        bmp280_sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=BMP280_ADDRESS)
        return bmp280_sensor
    except ValueError as e:
        print(f"Error: BMP280 sensor not found at address {BMP280_ADDRESS}. Check wiring and address.")
        return None
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def get_baseline_pressure(bmp280_sensor):
    """Collects baseline pressure readings and calculates the average."""
    print("Collecting baseline pressure. Keep sensor still...")
    pressure_readings = []
    for _ in range(10):
        try:
            pressure = bmp280_sensor.pressure
            pressure_readings.append(pressure)
            time.sleep(1)
        except OSError as e:
            print(f"Error reading pressure: {e}")
            continue  # Skip this reading and try again
    if not pressure_readings:
        print("Error: No pressure readings collected. Check sensor connection.")
        return None

    # Exclude the first two readings to avoid early sensor instability
    baseline_pressure = sum(pressure_readings[2:]) / len(pressure_readings[2:])
    print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
    return baseline_pressure

def read_and_display_altitude(bmp280_sensor, baseline_pressure):
    """Reads altitude and displays it."""
    try:
        altitude = bmp280_sensor.altitude
        print(f"Relative altitude: {altitude:.2f} meters")
    except OSError as e:
        print(f"Error reading altitude: {e}")

def main():
    """Main function to read and display altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return

    baseline_pressure = get_baseline_pressure(bmp280_sensor)
    if baseline_pressure is None:
        return

    try:
        while True:
            read_and_display_altitude(bmp280_sensor, baseline_pressure)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

