#!/usr/bin/env python3

"""
Raspberry Pi Python library for Aosong DHT20 Temperature and Humidity Sensor with CRC verification.
https://github.com/cjee21/RPi-DHT20

Functional implementation with enhanced error handling, performance optimizations, and best practices.
"""

import time
import logging
import smbus2 as smbus
from typing import Tuple, Optional

# Constants
DEFAULT_BUS = 1
DEFAULT_ADDRESS = 0x38
MEASUREMENT_DELAY = 0.08  # Maximum time to wait for measurement completion
INIT_DELAY = 0.5
MAX_MEASUREMENT_ATTEMPTS = 10
MAX_INIT_ATTEMPTS = 5
CRC_POLYNOMIAL = 0x31
CRC_INITIAL_VALUE = 0xFF

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20Error(Exception):
    """Custom exception for DHT20 sensor errors."""
    pass


def calculate_crc8(data: bytes) -> int:
    """Calculates the CRC-8 checksum."""
    crc = CRC_INITIAL_VALUE
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ CRC_POLYNOMIAL) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc


def read_register(bus: smbus.SMBus, address: int, register: int, length: int) -> Optional[bytes]:
    """Reads data from a register with error handling."""
    try:
        return bus.read_i2c_block_data(address, register, length)
    except OSError as e:
        logger.error(f"I2C read error: {e}")
        return None


def write_register(bus: smbus.SMBus, address: int, register: int, data: bytes) -> bool:
    """Writes data to a register with error handling."""
    try:
        bus.write_i2c_block_data(address, register, data)
        return True
    except OSError as e:
        logger.error(f"I2C write error: {e}")
        return False


def check_status(bus: smbus.SMBus, address: int) -> bool:
    """Checks the sensor status register."""
    status = read_register(bus, address, 0x71, 1)
    if status is None:
        return False
    return (status[0] & 0x18) == 0x18


def init_sensor(bus: smbus.SMBus, address: int) -> bool:
    """Initializes the sensor with retry mechanism."""
    for attempt in range(MAX_INIT_ATTEMPTS):
        if check_status(bus, address):
            logger.info("DHT20 sensor initialized successfully.")
            return True
        logger.warning(f"DHT20 sensor initialization attempt {attempt + 1} failed. Retrying in {INIT_DELAY} seconds...")
        time.sleep(INIT_DELAY)
    logger.error("DHT20 sensor initialization failed after multiple attempts.")
    return False


def trigger_measurement(bus: smbus.SMBus, address: int) -> bool:
    """Triggers a measurement."""
    return write_register(bus, address, 0xac, [0x33, 0x00])


def get_measurement_data(bus: smbus.SMBus, address: int) -> Optional[bytes]:
    """Retrieves measurement data with retry mechanism."""
    for attempt in range(MAX_MEASUREMENT_ATTEMPTS):
        time.sleep(MEASUREMENT_DELAY)
        status = read_register(bus, address, 0x71, 1)
        if status is None:
            return None
        if (status[0] & 0x80) == 0:
            data = read_register(bus, address, 0x71, 7)
            if data is None:
                return None
            return data
        logger.debug(f"DHT20 measurement in progress. Attempt {attempt + 1}/{MAX_MEASUREMENT_ATTEMPTS}")
    logger.error("DHT20 measurement timed out.")
    return None


def process_data(data: bytes) -> Tuple[Optional[float], Optional[float], bool]:
    """Processes the raw data and calculates CRC."""
    humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
    temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])

    humidity = humidity_raw / 2**20 * 100
    temperature = temperature_raw / 2**19 * 200 - 50

    calculated_crc = calculate_crc8(data[:-1])
    received_crc = data[6]

    crc_error = calculated_crc != received_crc

    if crc_error:
        logger.warning(f"CRC error detected! Calculated CRC: {calculated_crc:02X}, Received CRC: {received_crc:02X}")

    return temperature, humidity, crc_error


def get_temperature_and_humidity(bus: smbus.SMBus, address: int) -> Tuple[Optional[float], Optional[float], bool]:
    """Retrieves and processes temperature and humidity data."""
    if not trigger_measurement(bus, address):
        return None, None, True

    data = get_measurement_data(bus, address)
    if data is None:
        return None, None, True

    temperature, humidity, crc_error = process_data(data)
    return temperature, humidity, crc_error


class DHT20:
    """Class for interacting with the DHT20 sensor."""

    def __init__(self, bus_number: int = DEFAULT_BUS, address: int = DEFAULT_ADDRESS):
        self.bus_number = bus_number
        self.address = address
        self.bus: Optional[smbus.SMBus] = None
        self.last_temperature: Optional[float] = None
        self.last_humidity: Optional[float] = None
        self.last_measurement_time: Optional[float] = None
        self.min_measurement_interval = 2  # Minimum time between measurements in seconds

    def __enter__(self):
        """Context manager entry point."""
        if not self.begin():
            raise DHT20Error("Failed to initialize DHT20 sensor.")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point."""
        self.close()

    def begin(self) -> bool:
        """Initializes the sensor."""
        try:
            self.bus = smbus.SMBus(self.bus_number)
            if not init_sensor(self.bus, self.address):
                self.close()
                return False
            return True
        except Exception as e:
            logger.error(f"Failed to initialize DHT20 sensor: {e}")
            self.close()
            return False

    def close(self):
        """Closes the I2C bus."""
        if self.bus:
            try:
                self.bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        """Retrieves temperature and humidity, applying a minimum measurement interval."""
        if self.last_measurement_time is not None and time.time() - self.last_measurement_time < self.min_measurement_interval:
            return self.last_temperature, self.last_humidity, False

        if self.bus is None:
            logger.error("I2C bus not initialized. Call begin() first.")
            return None, None, True

        temperature, humidity, crc_error = get_temperature_and_humidity(self.bus, self.address)

        if not crc_error:
            self.last_temperature = temperature
            self.last_humidity = humidity
            self.last_measurement_time = time.time()

        return temperature, humidity, crc_error


def main():
    """Main function to demonstrate sensor usage."""
    try:
        with DHT20() as sensor:
            while True:
                temperature, humidity, crc_error = sensor.get_temperature_and_humidity()

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%, CRC Error: {crc_error}")
                else:
                    print("Failed to retrieve temperature and humidity.")

                time.sleep(2)

    except KeyboardInterrupt:
        print("Exiting program.")
    except DHT20Error as e:
        print(f"DHT20 Error: {e}")
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

