# Script Name: greenhouse_monitor.py
# Author: Bard
# Date: October 26, 2023
# Description: Reads temperature and humidity from a UART sensor and alerts on thresholds.
# Hardware Requirements: Raspberry Pi 4 Model B, UART sensor (e.g., DHT22)
# Software Requirements: Python 3, pyserial

import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Thresholds for alerts
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def read_sensor_data(serial_connection):
    """Reads a line from the serial port, parses it, and returns the temperature and humidity."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature, humidity = line.split(',')
            return float(temperature), float(humidity)
        else:
            return None, None
    except ValueError:
        print("Error: Malformed data received from sensor.")
        return None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if the temperature or humidity exceeds the defined thresholds and prints an alert."""
    if temperature is not None and humidity is not None:
        if temperature > TEMP_THRESHOLD:
            print(f"ALERT: Temperature exceeds threshold ({TEMP_THRESHOLD:.1f}°C) - Current: {temperature:.1f}°C")
        if humidity > HUMIDITY_THRESHOLD:
            print(f"ALERT: Humidity exceeds threshold ({HUMIDITY_THRESHOLD:.1f}%) - Current: {humidity:.1f}%")

def main():
    """Main function to read sensor data and check thresholds."""
    try:
        # Initialize serial connection
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Connected to serial port {SERIAL_PORT} at {BAUD_RATE} baud.")

            while True:
                # Read sensor data
                temperature, humidity = read_sensor_data(ser)

                # Check if data was successfully read
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    check_thresholds(temperature, humidity)

                # Wait before next reading
                time.sleep(1)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

