import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom communication protocol

# Constants
GPIO_MODE = GPIO.BCM
RECEIVE_INTERVAL = 0.1  # seconds

# Global Variables
server_running = False
log_file_path = None
receive_thread = None
log_file = None


def initialize_gpio():
    """Initializes GPIO settings."""
    try:
        GPIO.setwarnings(False)
        GPIO.setmode(GPIO_MODE)
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)


def cleanup_gpio():
    """Cleans up GPIO resources."""
    try:
        GPIO.cleanup()
        print("GPIO cleaned up.")
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")


def receive_data():
    """Continuously receives data and writes it to the log file."""
    global server_running, log_file
    while server_running:
        try:
            data = DOG.receive()
            if data:
                print(f"Received: {data}")
                log_file.write(data + "\n")
                log_file.flush()  # Ensure data is written immediately
        except Exception as e:
            print(f"Error receiving data: {e}")
            break  # Exit the loop on error
        time.sleep(RECEIVE_INTERVAL)


def start_server(filename):
    """Starts the data logging server."""
    global server_running, log_file_path, receive_thread, log_file

    if server_running:
        print("Server is already running.")
        return

    try:
        log_file = open(filename, 'a')
        log_file_path = filename
        print(f"Logging to: {filename}")
    except Exception as e:
        print(f"Error opening log file: {e}")
        return

    server_running = True
    receive_thread = threading.Thread(target=receive_data, daemon=True)
    receive_thread.start()
    print("Server started.")


def stop_server():
    """Stops the data logging server."""
    global server_running, receive_thread, log_file

    if not server_running:
        print("Server is not running.")
        return

    server_running = False
    if receive_thread:
        receive_thread.join()  # Wait for the receive thread to finish
    if log_file:
        log_file.close()
    print("Server stopped.")


def send_data(data):
    """Sends data using the DOGProtocol."""
    if not server_running:
        print("Server must be started first. Use the 'start' command.")
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(data):
    """Writes data directly to the log file."""
    if not server_running:
        print("Server must be started first. Use the 'start' command.")
        return
    try:
        log_file.write(data + "\n")
        log_file.flush()
        print(f"Wrote to log: {data}")
    except Exception as e:
        print(f"Error writing to log: {e}")


def display_log():
    """Displays the contents of the log file."""
    if not server_running:
        print("Server must be started first. Use the 'start' command.")
        return
    try:
        with open(log_file_path, 'r') as f:
            print(f.read())
    except FileNotFoundError:
        print("Log file not found.")
    except Exception as e:
        print(f"Error reading log file: {e}")


def print_help(command=None):
    """Prints help information."""
    help_messages = {
        "help": "Displays help information. Usage: help [command]",
        "start": "Starts the server. Usage: start <filename>",
        "stop": "Stops the server. Usage: stop",
        "send": "Sends data using DOGProtocol. Usage: send <data>",
        "write": "Writes data directly to the log file. Usage: write <data>",
        "display": "Displays the contents of the log file. Usage: display",
        "exit": "Exits the server. Usage: exit",
    }

    if command:
        print(help_messages.get(command, "No help found for this command."))
    else:
        print("Available commands:")
        for cmd in help_messages:
            print(f"  {cmd}")


def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    command_name = parts[0].lower()
    args = parts[1:]

    if command_name == "start":
        if len(args) == 1:
            start_server(args[0])
        else:
            print("Usage: start <filename>")
    elif command_name == "stop":
        stop_server()
    elif command_name == "send":
        send_data(" ".join(args))
    elif command_name == "write":
        write_to_log(" ".join(args))
    elif command_name == "display":
        display_log()
    elif command_name == "help":
        if args:
            print_help(args[0])
        else:
            print_help()
    elif command_name == "exit":
        stop_server()
        cleanup_gpio()
        sys.exit(0)
    else:
        print("Invalid command. Type 'help' for available commands.")


def main():
    """Main function."""
    initialize_gpio()

    try:
        while True:
            try:
                command = input("JAYES@ROVER53:\t")
                process_command(command)
            except KeyboardInterrupt:
                print("\nKeyboard interrupt. Type 'exit' to quit.")
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

