import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pin numbers using BCM numbering
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol Constants
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Transmission delay (seconds)
TRANSMISSION_DELAY = 0.0005

# Global variable to track program execution
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logging.info("Signal received, shutting down...")
    running = False

def initialize_gpio():
    """Initializes GPIO pins for output and input."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        GPIO.setup(DATA_OUT_PIN, GPIO.OUT)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT)
        GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Enable pull-down resistor
        GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN) # Enable pull-down resistor

        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        sys.exit(1)

def char_to_buffer(char):
    """Converts a character to its 8-bit buffer representation."""
    try:
        ascii_value = ord(char)
        return [0] + [int(bit) for bit in bin(ascii_value)[2:].zfill(7)]
    except TypeError:
        logging.error(f"Invalid character type: {type(char)}")
        return BASE_BUFFER

def buffer_to_char(buffer):
    """Converts an 8-bit buffer representation back to a character."""
    try:
        binary_string = "".join(map(str, buffer[1:]))
        return chr(int(binary_string, 2))
    except (TypeError, ValueError):
        logging.error(f"Invalid buffer format: {buffer}")
        return ''

def string_to_buffer_list(input_string):
    """Converts a string to a list of 8-bit buffers."""
    return [char_to_buffer(char) for char in input_string]

def buffer_list_to_string(buffer_list):
    """Converts a list of 8-bit buffers back to a string."""
    return "".join(buffer_to_char(buffer) for buffer in buffer_list if buffer not in (START_SIGNAL, END_SIGNAL))

def send_bit(bit):
    """Sends a single bit over the data and timer pins."""
    try:
        GPIO.output(DATA_OUT_PIN, bit)
        GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
        time.sleep(TRANSMISSION_DELAY)
        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
