import zmq
import time
import json
import RPi.GPIO as GPIO
import logging
import signal
import sys
from typing import Callable, Dict, Any, List

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_FREQUENCY = 1000  # Hz
DEFAULT_PWM_DUTY_CYCLE = 0.0
ERROR_OUTPUT_PIN = 10  # BCM GPIO 15
PWM_OUTPUT_PIN = 12  # BCM GPIO 18
WATCHDOG_TIMEOUT = 20  # seconds

# Global state (using a dictionary for immutability and thread safety)
global_state: Dict[str, Any] = {
    'model': {},
    'subscriptions': {},
    'last_msg': {},
    'error_state': False,
    'control_output': 0.0,
    'control_output_history': [],
    'pwm_frequency': DEFAULT_FREQUENCY,
    'pwm_duty_cycle': DEFAULT_PWM_DUTY_CYCLE,
    'pwm_enabled': False,
    'error_output_device': None,
    'output_device': None,
    'running': True,
}


def update_global_state(updates: Dict[str, Any]) -> Dict[str, Any]:
    """Updates the global state and returns the new state."""
    global global_state
    new_state = global_state.copy()
    new_state.update(updates)
    global_state = new_state
    return global_state


def get_global_state() -> Dict[str, Any]:
    """Returns the current global state."""
    global global_state
    return global_state


def handle_message(message: str, sub_callback: Callable[[Dict[str, Any]], None]) -> None:
    """Handles incoming messages and triggers callbacks."""
    try:
        data = json.loads(message)
        if 'cmd' in data:
            logger.info(f"Received command: {data['cmd']}")
            if data['cmd'] == 'SUBSCRIBE':
                handle_subscribe(data, sub_callback)
            elif data['cmd'] == 'UNSUBSCRIBE':
                handle_unsubscribe(data)
            elif data['cmd'] == 'UPDATE_PID':
                handle_update_pid(data)
            elif data['cmd'] == 'RESET':
                handle_reset(data)
            elif data['cmd'] == 'MUTE':
                handle_mute(data)
            elif data['cmd'] == 'UNMUTE':
                handle_unmute(data)
            elif data['cmd'] == 'SET_FREQUENCY':
                handle_set_frequency(data)
            elif data['cmd'] == 'SET_PWM_DUTY_CYCLE':
                handle_set_pwm_duty_cycle(data)
            elif data['cmd'] == 'SET_PWM_FREQUENCY':
                handle_set_pwm_frequency(data)
            elif data['cmd'] == 'OUTPUT':
                handle_output(data)
            else:
                logger.warning(f"Unknown command: {data['cmd']}")
        else:
            logger.warning("Invalid message format: Missing 'cmd' key.")
    except json.JSONDecodeError:
        logger.error("Invalid JSON message format.")
    except Exception as e:
        logger.exception(f"Error handling message: {e}")


def handle_subscribe(data: Dict[str, Any], sub_callback: Callable[[Dict[str, Any]], None]) -> None:
    """Handles SUBSCRIBE command."""
    if 'stream_filter' not in data:
        logger.error("SUBSCRIBE command missing 'stream_filter' key.")
        return

    stream_filter = data['stream_filter']
    if stream_filter not in get_global_state()['subscriptions']:
        get_global_state()['subscriptions'][stream_filter] = []

    get_global_state()['subscriptions'][stream_filter].append({
        'callback': sub_callback,
        'kwargs': data.get('kwargs', {}),
        'control': data.get('control', True),
        'mute': data.get('mute', False)
    })
    logger.info(f"Subscribed to: {stream_filter}")


def handle_unsubscribe(data: Dict[str, Any]) -> None:
    """Handles UNSUBSCRIBE command."""
    if 'stream_filter' not in data:
        logger.error("UNSUBSCRIBE command missing 'stream_filter' key.")
        return

    stream_filter = data['stream_filter']
    if stream_filter in get_global_state()['subscriptions']:
        del get_global_state()['subscriptions'][stream_filter]
        logger.info(f"Unsubscribed from: {stream_filter}")
    else:
        logger.warning(f"Not subscribed to: {stream_filter}")


def handle_update_pid(data: Dict[str, Any]) -> None:
    """Handles UPDATE_PID command."""
    if 'pid_id' not in data:
        logger.error("UPDATE_PID command missing 'pid_id' key.")
        return

    pid_id = data['pid_id']
    model = get_global_state()['model']

    if pid_id not in model:
        model[pid_id] = {}

    for param in ['P', 'I', 'D', 'integral_limit', 'output_limit']:
        if param in data:
            model[pid_id][param] = data[param]

    logger.info(f"Updated PID parameters for: {pid_id}")


def handle_reset(data: Dict[str, Any]) -> None:
    """Handles RESET command."""
    if 'pid_id' not in data:
        logger.error("RESET command missing 'pid_id' key.")
        return

    pid_id = data['pid_id']
    model = get_global_state()['model']

    if pid_id in model:
        model[pid_id]['last_error'] = 0.0
        model[pid_id]['integral'] = 0.0
        logger.info(f"Reset PID state for: {pid_id}")
    else:
        logger.warning(f"PID not found for reset: {pid_id}")


def handle_mute(data: Dict[str, Any]) -> None:
    """Handles MUTE command."""
    if 'stream_filter' not in data:
        logger.error("MUTE command missing 'stream_filter' key.")
        return

    stream_filter = data['stream_filter']
    subscriptions = get_global_state()['subscriptions']

    if stream_filter in subscriptions:
        for sub in subscriptions[stream_filter]:
            sub['mute'] = True
        logger.info(f"Muted: {stream_filter}")
    else:
        logger.warning(f"Not subscribed to: {stream_filter}")


def handle_unmute(data: Dict[str, Any]) -> None:
    """Handles UNMUTE command."""
    if 'stream_filter' not in data:
        logger.error("UNMUTE command missing 'stream_filter' key.")
        return

    stream_filter = data['stream_filter']
    subscriptions = get_global_state()['subscriptions']

    if stream_filter in subscriptions:
        for sub in subscriptions[stream_filter]:
            sub['mute'] = False
        logger.info(f"Unmuted: {stream_filter}")
    else:
        logger.warning(f"Not subscribed to: {stream_filter}")


def handle_set_frequency(data: Dict[str, Any]) -> None:
    """Handles SET_FREQUENCY command."""
    if 'frequency' not in data:
        logger.error("SET_FREQUENCY command missing 'frequency' key.")
        return

    frequency = data['frequency']
    try:
        frequency = float(frequency)
        if frequency <= 0:
            raise ValueError("Frequency must be a positive number.")

        update_global_state({'pwm_frequency': frequency})
        logger.info(f"Set PWM frequency to: {frequency} Hz")
        apply_pwm_settings()
    except ValueError as e:
        logger.error(f"Invalid frequency value: {e}")


def handle_set_pwm_duty_cycle(data: Dict[str, Any]) -> None:
    """Handles SET_PWM_DUTY_CYCLE command."""
    if 'duty_cycle' not in data:
        logger.error("SET_PWM_DUTY_CYCLE command missing 'duty_cycle' key.")
        return

    duty_cycle = data['duty_cycle']
    try:
        duty_cycle = float(duty_cycle)
        if not 0.0 <= duty_cycle <= 100.0:
            raise ValueError("Duty cycle must be between 0.0 and 100.0.")

        update_global_state({'pwm_duty_cycle': duty_cycle})
        logger.info(f"Set PWM duty cycle to: {duty_cycle}%")
        apply_pwm_settings()
    except ValueError as e:
        logger.error(f"Invalid duty cycle value: {e}")


def handle_set_pwm_frequency(data: Dict[str, Any]) -> None:
    """Handles SET_PWM_FREQUENCY command."""
    if 'frequency' not in data:
        logger.error("SET_PWM_FREQUENCY command missing 'frequency' key.")
        return

    frequency = data['frequency']
    try:
        frequency = float(frequency)
        if frequency <= 0:
            raise ValueError("Frequency must be a positive number.")

        update_global_state({'pwm_frequency': frequency})
        logger.info(f"Set PWM frequency to: {frequency} Hz")
        apply_pwm_settings()
    except ValueError as e:
        logger.error(f"Invalid frequency value: {e}")


def handle_output(data: Dict[str, Any]) -> None:
    """Handles OUTPUT command."""
    if 'value' not in data:
        logger.error("OUTPUT command missing 'value' key.")
        return

    value = data['value']
    try:
        value = float(value)
        update_global_state({'control_output': value})
        logger.info(f"Set control output to: {value}")
        apply_pwm_settings()
    except ValueError:
        logger.error("Invalid output value. Must be a number.")


def apply_pwm_settings() -> None:
    """Applies PWM settings to the PWM output device."""
    state = get_global_state()
    if state['pwm_enabled']:
        try:
            if state['pwm_device']:
                state['pwm_device'].frequency = state['pwm_frequency']
                state['pwm_device'].duty_cycle = state['pwm_duty_cycle']
            else:
                logger.warning("PWM device not initialized.")
        except Exception as e:
            logger.exception(f"Error applying PWM settings: {e}")


def update_error_output() -> None:
    """Updates the error output signal based on the global error state."""
    state = get_global_state()
    if state['error_output_device']:
        try:
            if state['global_err_state']:
                if state['pwm_enabled']:
                    state['error_output_device'].value = 1.0  # Full brightness
                else:
                    state['error_output_device'].on()
            else:
                if state['pwm_enabled']:
                    state['error_output_device'].value = 0.0  # Off
                else:
                    state['error_output_device'].off()
        except Exception as e:
            logger.exception(f"Error updating error output: {e}")
    else:
        logger.warning("Error output device not initialized.")


def set_error_output(state: bool) -> None:
    """Directly sets the error output state."""
    global_state['global_err_state'] = state
    update_error_output()


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logger.info("Received signal, shutting down...")
    global_state['running'] = False


def main_loop(sub_socket: zmq.Socket, sub_callback: Callable[[Dict[str, Any]], None]) -> None:
    """Main loop for receiving messages and handling subscriptions."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logger.info("Starting main loop...")

    while global_state['running']:
        try:
            sub_socket.poll(timeout=1000)  # Check for messages every 1 second

            if sub_socket.getsockopt(zmq.EVENTS) & zmq.POLLIN:
                try:
                    message = sub_socket.recv(flags=zmq.NOBLOCK)
                    handle_message(message.decode(), sub_callback)
                    update_global_state({'last_msg': time.time()})
                except zmq.ZMQError as e:
                    if e.errno == zmq.EAGAIN:
                        # No message received, continue looping
                        pass
                    else:
                        logger.exception(f"ZMQError receiving message: {e}")

            # Watchdog timer
            current_time = time.time()
            if current_time - get_global_state()['last_msg'] > WATCHDOG_TIMEOUT:
                logger.warning("Watchdog timeout! Triggering error output.")
                set_error_output(True)
            else:
                set_error_output(False)

        except Exception as e:
            logger.exception(f"Error in main loop: {e}")
            time.sleep(1)  # Prevent excessive logging in case of continuous errors

    logger.info("Exiting main loop.")


def initialize_gpio() -> None:
    """Initializes GPIO pins for PWM and error output."""
    global global_state
    try:
        GPIO.setmode(GPIO.BOARD)  # Use physical pin numbering

        # Initialize PWM output
        global_state['pwm_enabled'] = True
        global_state['pwm_device'] = None

        try:
            from gpiozero import PWMOutputDevice
            global_state['pwm_device'] = PWMOutputDevice(PWM_OUTPUT_PIN, frequency=DEFAULT_FREQUENCY, initial_value=DEFAULT_PWM_DUTY_CYCLE)
            logger.info(f"Initialized PWM output on pin {PWM_OUTPUT_PIN}")
        except ImportError:
            logger.warning("gpiozero library not found. PWM output will be disabled.")
            global_state['pwm_enabled'] = False
        except Exception as e:
            logger.exception(f"Error initializing PWM output: {e}")
            global_state['pwm_enabled'] = False

        # Initialize error output
        try:
            from gpiozero import OutputDevice
            global_state['error_output_device'] = OutputDevice(ERROR_OUTPUT_PIN, active_high=True, initial_value=False)
            logger.info(f"Initialized error output on pin {ERROR_OUTPUT_PIN}")
        except ImportError:
            logger.warning("gpiozero library not found. Error output will be disabled.")
            global_state['error_output_device'] = None
        except Exception as e:
            logger.exception(f"Error initializing error output: {e}")
            global_state['error_output_device'] = None

        update_error_output()  # Ensure initial state

    except RuntimeError as e:
        logger.error(f"Error initializing GPIO: {e}.  Are you running as root?")
        global_state['error_output_device'] = None
    except Exception as e:
        logger.exception(f"Unexpected error during GPIO initialization: {e}")
        global_state['error_output_device'] = None


def cleanup_gpio() -> None:
    """Cleans up GPIO resources."""
    global global_state
    logger.info("Cleaning up GPIO...")
    try:
        if global_state['pwm_device']:
            global_state['pwm_device'].close()
        if global_state['error_output_device']:
            global_state['error_output_device'].close()
        GPIO.cleanup()
        logger.info("GPIO cleanup complete.")
    except Exception as e:
        logger.exception(f"Error during GPIO cleanup: {e}")


class PIDHandler:
    """
    A class to manage PID controllers and error output for a Raspberry Pi.

    This class receives data via ZMQ subscriptions, updates PID controllers,
    and controls error output based on the current state.
    """

    def __init__(self, logger_name: str = __name__):
        """
        Initializes the PIDHandler.

        Args:
            logger_name (str): The name of the logger to use.
        """
        self.logger = logging.getLogger(logger_name)
        self.context = zmq.Context()
        self.sub_socket = self.context.socket(zmq.SUBSCRIBE)
        self.global_state = get_global_state()
        self.global_state['last_msg'] = time.time()  # Initialize last message time

    def connect(self, endpoint: str) -> None:
        """
        Connects to the specified ZMQ endpoint.

        Args:
            endpoint (str): The ZMQ endpoint to connect to.
        """
        try:
            self.sub_socket.connect(endpoint)
            self.logger.info(f"Connected to ZMQ endpoint: {endpoint}")
        except zmq.ZMQError as e:
            self.logger.error(f"Error connecting to ZMQ endpoint: {e}")
            raise

    def run(self, sub_callback: Callable[[Dict[str, Any]], None]) -> None:
        """
        Runs the PID handler, receiving data and updating PID controllers.

        Args:
            sub_callback (Callable[[Dict[str, Any]], None]): A callback function
                to be called for each received data point.  The callback function
                should accept a dictionary containing the data point.
        """
        try:
            initialize_gpio()
            main_loop(self.sub_socket, sub_callback)
        except KeyboardInterrupt:
            self.logger.info("Keyboard interrupt received. Shutting down...")
        except Exception as e:
            self.logger.exception(f"An unexpected error occurred: {e}")
        finally:
            cleanup_gpio()
            self.sub_socket.close()
            self.context.term()
            self.logger.info("PIDHandler stopped.")

