# A simple fingerprint authentication script for Raspberry Pi 5 using an Adafruit Fingerprint sensor.

import time
import board
import busio
import adafruit_fingerprint

# Define the I2C address of the fingerprint sensor
FINGERPRINT_SENSOR_ADDRESS = 0x26

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C: {e}.  Check if I2C is enabled.")
        return None
    except Exception as e:
        print(f"An unexpected error occurred during I2C initialization: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return fingerprint_sensor
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}. Check sensor connection and address.")
        return None
    except Exception as e:
        print(f"An unexpected error occurred during fingerprint sensor initialization: {e}")
        return None

def get_fingerprint_image(fingerprint_sensor):
    """Acquires a fingerprint image from the sensor."""
    try:
        print("Waiting for fingerprint...")
        while fingerprint_sensor.get_image() != adafruit_fingerprint.OK:
            pass  # Wait for a valid image
        return True
    except Exception as e:
        print(f"Error getting fingerprint image: {e}")
        return False

def convert_image_to_template(fingerprint_sensor):
    """Converts the acquired image to a template."""
    try:
        if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            print("Error converting image to template.")
            return False
        return True
    except Exception as e:
        print(f"Error converting image to template: {e}")
        return False

def search_fingerprint_database(fingerprint_sensor):
    """Searches the fingerprint database for a match."""
    try:
        if fingerprint_sensor.finger_search() != adafruit_fingerprint.OK:
            print("No fingerprint match found.")
            return None, None
        return fingerprint_sensor.finger_id, fingerprint_sensor.confidence
    except Exception as e:
        print(f"Error searching fingerprint database: {e}")
        return None, None

def grant_access(user_id, confidence_score):
    """Grants access to the system."""
    print(f"Access Granted for User ID: {user_id}, Confidence Score: {confidence_score}")

def deny_access():
    """Denies access to the system."""
    print("Access Denied")

def main():
    """Main function to run the fingerprint authentication."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        return

    try:
        while True:
            if get_fingerprint_image(fingerprint_sensor):
                if convert_image_to_template(fingerprint_sensor):
                    user_id, confidence_score = search_fingerprint_database(fingerprint_sensor)
                    if user_id is not None:
                        grant_access(user_id, confidence_score)
                    else:
                        deny_access()
            time.sleep(1)  # Wait before next attempt

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for I2C or the fingerprint sensor in this library,
        # but good practice to include a finally block for potential future expansion.
        print("Program finished.")

if __name__ == "__main__":
    main()

