# Rotary Encoder Class for Raspberry Pi
# Designed for KY-040 rotary encoder
# Uses gpiozero library

import time
from gpiozero import DigitalInputDevice

class RotaryEncoder:
    """
    A class to represent a rotary encoder connected to a Raspberry Pi.
    """

    def __init__(self, clk_pin, dt_pin, callback=None, debounce_time=0.005):
        """
        Initializes the RotaryEncoder object.

        Args:
            clk_pin (int): GPIO pin number for the CLK signal.
            dt_pin (int): GPIO pin number for the DT signal.
            callback (callable, optional): Function to call when the encoder value changes. 
                                            Defaults to None.  The callback function should accept one argument: the current encoder value.
            debounce_time (float, optional): Debounce time in seconds. Defaults to 0.005.
        """
        try:
            self.clk = DigitalInputDevice(clk_pin, pull_up=True)
            self.dt = DigitalInputDevice(dt_pin, pull_up=True)
        except Exception as e:
            raise RuntimeError(f"Error initializing GPIO pins: {e}")

        self.value = 0
        self.last_clk_state = self.clk.value
        self.callback = callback
        self.debounce_time = debounce_time

        if self.callback and not callable(self.callback):
            raise TypeError("Callback must be callable")

        self.clk.when_activated = self._on_clk_rising
        self.clk.when_deactivated = self._on_clk_falling


    def _on_clk_rising(self):
        """
        Internal callback function for CLK rising edge.
        """
        current_time = time.time()
        if current_time - self.last_clk_state < self.debounce_time:
            return

        self.last_clk_state = current_time
        if self.dt.value != self.clk.value:
            self.value += 1
        else:
            self.value -= 1

        if self.callback:
            try:
                self.callback(self.value)
            except Exception as e:
                print(f"Error in callback function: {e}")


    def _on_clk_falling(self):
        """
        Internal callback function for CLK falling edge.
        """
        current_time = time.time()
        if current_time - self.last_clk_state < self.debounce_time:
            return

        self.last_clk_state = current_time
        if self.dt.value != self.clk.value:
            self.value -= 1
        else:
            self.value += 1

        if self.callback:
            try:
                self.callback(self.value)
            except Exception as e:
                print(f"Error in callback function: {e}")


    def cleanup(self):
        """
        Releases GPIO resources.
        """
        self.clk.close()
        self.dt.close()


if __name__ == "__main__":
    # Example usage:
    def my_callback(value):
        print(f"Encoder value: {value}")

    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=my_callback)
        print("Rotary encoder example. Press Ctrl+C to exit.")
        while True:
            time.sleep(0.1)  # Reduce CPU usage
    except KeyboardInterrupt:
        print("Exiting...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if 'encoder' in locals():
            encoder.cleanup()

