#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus2
import time
import datetime
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_I2C_BUS = 1
DEFAULT_I2C_ADDRESS = 0x68
DEFAULT_CENTURY = 21

# Register addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# Global variable to track the I2C bus handle
bus = None

def bcd_to_int(bcd):
    """Converts Binary Coded Decimal (BCD) to integer."""
    try:
        return int(bcd / 16) * 10 + int(bcd % 16)
    except TypeError:
        logger.error("Invalid BCD value: %s", bcd)
        raise ValueError("Invalid BCD value")

def int_to_bcd(integer):
    """Converts integer to Binary Coded Decimal (BCD)."""
    if not 0 <= integer <= 99:
        raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
    return int(integer / 10) * 16 + int(integer % 10)

def validate_time_component(value, min_val, max_val, component_name):
    """Validates a time component (hour, minute, second)."""
    if not min_val <= value <= max_val:
        raise ValueError(f"Invalid {component_name} value: {value}. Must be between {min_val} and {max_val}.")

def validate_datetime_component(value, min_val, max_val, component_name):
    """Validates a datetime component (day, month, year)."""
    if not min_val <= value <= max_val:
        raise ValueError(f"Invalid {component_name} value: {value}. Must be between {min_val} and {max_val}.")

def read_register(register_address):
    """Reads a byte from the specified register."""
    global bus
    try:
        return bus.read_byte_data(DEFAULT_I2C_ADDRESS, register_address)
    except IOError as e:
        logger.error("I2C read error: %s", e)
        raise

def write_register(register_address, value):
    """Writes a byte to the specified register."""
    global bus
    try:
        bus.write_byte_data(DEFAULT_I2C_ADDRESS, register_address, value)
    except IOError as e:
        logger.error("I2C write error: %s", e)
        raise

def read_seconds():
    """Reads the seconds from the RTC."""
    return bcd_to_int(read_register(REG_SECONDS) & 0x7F)

