#!/usr/bin/env python3

import json
import time
import logging
import threading
import signal
import sys
from flask import Flask, jsonify, request, Response, abort
import serial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DATA_STORE = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]
MAX_DATA_STORE_SIZE = 100
SERVER_HOST = '0.0.0.0'
SERVER_PORT = 5000

# Global variables
app = Flask(__name__)
serial_port = None
data_lock = threading.Lock()
shutdown_event = threading.Event()

class SerialCommunicator:
    """
    Manages serial communication with the instrument.
    """
    def __init__(self, port=DEFAULT_SERIAL_PORT, baudrate=DEFAULT_BAUDRATE):
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def __enter__(self):
        """Context manager entry."""
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit."""
        self.close()

    def open(self):
        """Opens the serial port."""
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            logging.info(f"Serial port {self.port} opened successfully.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def send(self, cmd):
        """Sends a command to the instrument and returns the response."""
        if not self.ser:
            raise serial.SerialException("Serial port is not open.")

        try:
            self.ser.write(cmd.encode('ascii'))
            response = self.receive_line()
            if response is None:
                raise serial.SerialException("Timeout waiting for response.")
            return response
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            raise

    def receive_line(self):
        """Receives a line from the instrument."""
        try:
            line = self.ser.readline().decode('ascii', errors='replace').strip()
            return line
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None

    def close(self):
        """Closes the serial port."""
        if self.ser and self.ser.is_open:
            self.ser.close()
            logging.info("Serial port closed.")

class DataManager:
    """
    Manages the in-memory data store.
    """
    def __init__(self, initial_data=DATA_STORE):
        self.data = initial_data
        self.next_id = max(item['id'] for item in self.data) + 1 if self.data else 1
        self.max_size = MAX_DATA_STORE_SIZE

    def get_all(self):
        """Returns all data items."""
        with data_lock:
            return self.data

    def get_by_id(self, item_id):
        """Returns a data item by ID."""
        with data_lock:
            item = next((item for item in self.data if item['id'] == item_id), None)
            return item

    def create(self, name, done):
        """Creates a new data item."""
        with data_lock:
            if len(self.data) >= self.max_size:
                self.data.pop(0)  # Remove the oldest item
            item = {"id": self.next_id, "name": name, "done": done}
            self.data.append(item)
            self.next_id += 1
            return item

# Initialize data manager
data_manager = DataManager()

@app.route('/version', methods=['GET'])
def get_instrument_version():
    """
    Retrieves the instrument version information.
    """
    try:
        with SerialCommunicator() as comm:
            response = comm.send('*IDN?\n')
            if response:
                return Response(response, mimetype='text/plain')
            else:
                return Response("No response received from instrument.", status=504)
    except serial.SerialException as e:
        logging.error(f"Failed to get instrument version: {e}")
        return Response(str(e), status=500)
    except Exception as e:
        logging.error(f"Unexpected error getting instrument version: {e}")
        return Response(str(e), status=500)

@app.route('/data', methods=['GET'])
def get_all_data():
    """
    Returns all data items as a JSON list.
    """
    data = data_manager.get_all()
    return jsonify(data)

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    """
    Returns a specific data item by ID.
    """
    item = data_manager.get_by_id(item_id)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found", status=404)

@app.route('/data', methods=['POST'])
def create_data_item():
    """
    Creates a new data item.
    """
    try:
        name = request.json.get('name')
        done = request.json.get('done', False)

        if not isinstance(name, str) or not isinstance(done, bool):
            return Response("Invalid input data. 'name' must be a string and 'done' must be a boolean.", status=400)

        if not name:
            return Response("Name cannot be empty.", status=400)

        item = data_manager.create(name, done)
        return jsonify(item), 201
    except Exception as e:
        logging.error(f"Failed to create data item: {e}")
        return Response(str(e), status=500)

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info(f"Received signal {sig}. Shutting down...")
    shutdown_event.set()

def run_server():
    """Runs the Flask server in a separate thread."""
    try:
        app.run(host=SERVER_HOST, port=SERVER_PORT, debug=False)
    except Exception as e:
        logging.error(f"Flask server error: {e}")
    finally:
        logging.info("Flask server stopped.")

def main():
    """Main function to start the application."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start the Flask server in a separate thread
    server_thread = threading.Thread(target=run_server)
    server_thread.daemon = True  # Allow the main thread to exit even if the server thread is running
    server_thread.start()

    logging.info("Application started. Press Ctrl+C to exit.")

    # Wait for the shutdown event
    shutdown_event.wait()

    # Clean up resources
    logging.info("Cleaning up resources...")
    if serial_port:
        try:
            serial_port.close()
            logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")

    logging.info("Application stopped.")

if __name__ == '__main__':
    main()

