@app.route('/version', methods=['GET'])
def get_instrument_version():
    """
    Retrieves the instrument version information from the connected device via serial communication.
    Returns the version string as HTML with line breaks for better readability.
    Handles potential serial communication errors and returns an HTTP 503 error if the version cannot be retrieved.
    """
    if serial_connection is None:
        return Response("Serial port not initialized", status=503, mimetype='text/html')

    try:
        serial_connection.write(b'*IDN?\n')
        time.sleep(0.1)  # Allow time for the response to be sent
        response_data = serial_connection.read(1000)  # Read up to 1000 bytes
        version_info = response_data.decode('utf-8', errors='ignore').replace('\n', '<br><br>')
        return Response(version_info, mimetype='text/html')
    except serial.SerialException as e:
        print(f"Error communicating with instrument: {e}")
        return Response(f"Error: Could not retrieve version information. Serial communication error: {e}", status=503, mimetype='text/html')
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return Response(f"Error: Could not retrieve version information. An unexpected error occurred: {e}", status=503, mimetype='text/html')
    finally:
        # Ensure the serial port is closed in case of an error
        if serial_connection and serial_connection.is_open:
            serial_connection.close()


