    """
    if request.headers['Content-Type'] == 'application/json':
        try:
            request_data = request.get_json()
            item_id = request_data.get('id')
            item_name = request_data.get('name')
            item_done = request_data.get('done', False)  # Default to False if not provided

            if not isinstance(item_id, int) or not isinstance(item_name, str):
                abort(400, description="Invalid data type. 'id' must be an integer and 'name' must be a string.")

            existing_item = next((item for item in data_store if item['id'] == item_id), None)
            if existing_item:
