            new_item = {"id": item_id, "name": item_name, "done": item_done}
            data_store.append(new_item)
            return jsonify(data_store)

        except (json.JSONDecodeError, KeyError, TypeError) as e:
            abort(400, description=f"Invalid JSON data: {e}")

    elif request.headers['Content-Type'] == 'application/x-www-form-urlencoded':
        try:
            item_id = int(request.form['id'])
            item_name = request.form['name']
            item_done = request.form.get('done', False)  # Default to False if not provided

            existing_item = next((item for item in data_store if item['id'] == item_id), None)
            if existing_item:
                abort(400, description=f"An item with ID {item_id} already exists.")

            new_item = {"id": item_id, "name": item_name, "done": item_done}
            data_store.append(new_item)
            return jsonify(data_store)

        except (KeyError, ValueError) as e:
            abort(400, description=f"Invalid form data: {e}")

    else:
        abort(415, description="Unsupported media type. Please use application/json or application/x-www-form-urlencoded.")


@app.route('/postjson', methods=['GET'])
def get_all_data_get():
